package local.tvmorph.tv;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.widget.Toast;import java.net.*;import java.io.*;import java.util.*;
final class TvUpdater {
 private static volatile boolean busy;private static boolean pending;
 static URL source(String value)throws Exception{return source(value,false);}
 static URL source(String value,boolean iptv)throws Exception{URL url=new URL(value);String host=url.getHost();if(!url.getProtocol().equals("http")||url.getPort()!=8788||!url.getPath().equals(iptv?"/morph-iptv.apk":"/tv-morph.apk")||url.getUserInfo()!=null||url.getQuery()!=null||url.getRef()!=null||!host.matches("[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+"))throw new IOException("Invalid update source");InetAddress address=InetAddress.getByName(host);if(!(address instanceof Inet4Address)||!address.isSiteLocalAddress()||address.isLoopbackAddress())throw new IOException("Invalid update network");return url;}
 static void verify(Context c,File apk)throws Exception{verify(c,apk,false);}
 static void verify(Context c,File apk,boolean iptv)throws Exception{PackageManager pm=c.getPackageManager();PackageInfo own=pm.getPackageInfo(c.getPackageName(),PackageManager.GET_SIGNATURES),incoming=pm.getPackageArchiveInfo(apk.getAbsolutePath(),PackageManager.GET_SIGNATURES);if(incoming==null||!(iptv?"local.morph.iptv":c.getPackageName()).equals(incoming.packageName)||!iptv&&incoming.versionCode<own.versionCode||incoming.signatures==null||own.signatures==null||incoming.signatures.length!=1||own.signatures.length!=1||!incoming.signatures[0].equals(own.signatures[0]))throw new IOException("Update package identity or signature rejected");if(iptv)try{PackageInfo installed=pm.getPackageInfo("local.morph.iptv",0);if(incoming.versionCode<installed.versionCode)throw new IOException("IPTV downgrade rejected");}catch(PackageManager.NameNotFoundException firstInstall){}}
 static synchronized void start(Activity activity,String value)throws Exception{start(activity,value,false);}
 static synchronized void startIptv(Activity activity,String value)throws Exception{start(activity,value,true);}
 private static synchronized void start(Activity activity,String value,boolean iptv)throws Exception{final URL url=source(value,iptv);if(busy)throw new IOException("Update already in progress");busy=true;Toast.makeText(activity,UiSettings.text(activity,"جاري استلام التحديث من الموبايل…","Receiving update from phone…"),Toast.LENGTH_LONG).show();new Thread(()->{File partial=new File(activity.getCacheDir(),"update-partial.apk");HttpURLConnection connection=null;try{connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(5000);connection.setReadTimeout(15000);connection.setInstanceFollowRedirects(false);if(connection.getResponseCode()!=200)throw new IOException("Download failed");int total=0;try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(partial)){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1){total+=n;if(total>32*1024*1024)throw new IOException("Update too large");out.write(buffer,0,n);}}if(total<10000)throw new IOException("Invalid update");verify(activity,partial,iptv);File verified=new File(activity.getCacheDir(),"verified-update.apk");if(!partial.renameTo(verified))throw new IOException("Could not stage update");activity.runOnUiThread(()->{pending=true;prompt(activity);});}catch(Exception e){partial.delete();activity.runOnUiThread(()->new AlertDialog.Builder(activity).setTitle("Morph TV").setMessage(UiSettings.text(activity,"تعذّر استلام تحديث موثوق. جدّد الرابط من الموبايل وجرّب تاني.","Could not receive a verified update. Refresh the phone download link and retry.")).setPositiveButton("OK",null).show());}finally{if(connection!=null)connection.disconnect();busy=false;}},"tv-morph-update").start();}
 static synchronized boolean reserveOfficial(){if(busy||pending)return false;busy=true;return true;}
 static synchronized void releaseOfficial(){busy=false;}
 static void installVerified(Activity activity){pending=true;prompt(activity);}
 static void resume(Activity activity){if(pending&&activity.getPackageManager().canRequestPackageInstalls())prompt(activity);}
 private static void prompt(Activity activity){if(!pending||activity.isFinishing())return;try{if(!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle(UiSettings.text(activity,"السماح بتحديث التطبيق","Allow app updates")).setMessage(UiSettings.text(activity,"فعّل السماح بالتثبيت لهذا التطبيق، وبعد الرجوع وافق على تحديث التطبيق.","Allow this app to install updates, then return and approve the update.")).setPositiveButton(UiSettings.text(activity,"فتح الإعدادات","Open settings"),(d,w)->{try{activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));}catch(Exception e){pending=false;}}).setNegativeButton(UiSettings.text(activity,"إلغاء","Cancel"),(d,w)->pending=false).show();return;}pending=false;Uri uri=Uri.parse("content://"+activity.getPackageName()+".updates/tv-morph.apk");Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);}catch(Exception e){pending=false;Toast.makeText(activity,UiSettings.text(activity,"افتح ملف التحديث من المتصفح بدلًا من ذلك.","Open the update file from the browser instead."),Toast.LENGTH_LONG).show();}}
}
